  - name: "SS2022"
    type: ss
    server: "${server}"
    port: ${route_ss_port}
    cipher: "2022-blake3-aes-128-gcm"
    password: "${SS_PASSWORD}"
    udp: true
  - name: "AnyTLS"
    type: anytls
    server: "${server}"
    port: ${route_anytls_port}
    password: "${ANYTLS_PASSWORD}"
    sni: "${DOMAIN}"
    alpn: [h2, http/1.1]
    client-fingerprint: chrome
    skip-cert-verify: false
EOF
  if [[ "$route_anyreality_enabled" == "true" && -n "$route_anyreality_port" ]]; then
    cat <<EOF
  - name: "AnyReality"
    type: anytls
    server: "${server}"
    port: ${route_anyreality_port}
    password: "${ANYREALITY_PASSWORD}"
    sni: "${DOMAIN}"
    client-fingerprint: chrome
    reality-opts:
      public-key: "${ANYREALITY_PUBLIC_KEY}"
      short-id: "${ANYREALITY_SHORT_ID}"
    skip-cert-verify: false
EOF
  fi
  cat <<EOF
  - name: "Trojan-TLS"
    type: trojan
    server: "${server}"
    port: ${route_trojan_port}
    password: "${TROJAN_PASSWORD}"
    sni: "${DOMAIN}"
    udp: true
    skip-cert-verify: false
  - name: "VLESS-Reality-Vision"
    type: vless
    server: "${server}"
    port: ${route_vision_port}
    uuid: "${VISION_UUID}"
    encryption: ""
    network: tcp
    tls: true
    udp: true
    flow: xtls-rprx-vision
    servername: "${DOMAIN}"
    client-fingerprint: chrome
    reality-opts:
      public-key: "${VISION_PUBLIC_KEY}"
      short-id: "${VISION_SHORT_ID}"
    skip-cert-verify: false
  - name: "VLESS-Reality-XHTTP"
    type: vless
    server: "${server}"
    port: ${route_xhttp_port}
    uuid: "${XHTTP_UUID}"
    encryption: ""
    network: xhttp
    tls: true
    udp: true
    alpn: [h2]
    servername: "${DOMAIN}"
    client-fingerprint: chrome
    reality-opts:
      public-key: "${XHTTP_PUBLIC_KEY}"
      short-id: "${XHTTP_SHORT_ID}"
    xhttp-opts:
      path: "${XHTTP_PATH}"
      host: "${DOMAIN}"
      mode: stream-one
    skip-cert-verify: false
EOF
  } | write_atomic "$target"
}

route_context_fail() {
  printf '线路上下文无效：%s\n' "$*" >&2
  return 64
}

# A route context is a validated associative array. Callers declare routing and
# DNS intent by name; this file alone expands the selected normal/cross ports.
route_context_is_associative() {
  local context_name="${1:-}" declaration
  [[ "$context_name" =~ ^[a-zA-Z_][a-zA-Z0-9_]*$ ]] || return 1
  declaration="$(declare -p "$context_name" 2>/dev/null)" || return 1
  [[ "$declaration" == 'declare -A '* ]]
}

route_context_port_is_valid() {
  local value="${1:-}"
  [[ "$value" =~ ^[0-9]+$ ]] || return 1
  (( 10#$value >= 1 && 10#$value <= 65535 ))
}

route_context_set_ports() {
  local context_name="${1:-}" port_set="${2:-}"
  route_context_is_associative "$context_name" \
    || route_context_fail "必须传入关联数组。" || return
  local -n route_ports_ref="$context_name"

  case "$port_set" in
    normal)
      route_ports_ref["hy2_start"]="$HY2_START"
      route_ports_ref["hy2_end"]="$HY2_END"
      route_ports_ref["tuic_port"]="$TUIC_PORT"
      route_ports_ref["ss_port"]="$SS_PORT"
      route_ports_ref["anytls_port"]="$ANYTLS_PORT"
      route_ports_ref["trojan_port"]="$TROJAN_PORT"
      route_ports_ref["vision_port"]="$VISION_PORT"
      route_ports_ref["xhttp_port"]="$XHTTP_PORT"
      route_ports_ref["anyreality_port"]="${ANYREALITY_PORT:-}"
      ;;
    cross)
      route_ports_ref["hy2_start"]="$CROSS_HY2_START"
      route_ports_ref["hy2_end"]="$CROSS_HY2_END"
      route_ports_ref["tuic_port"]="$CROSS_TUIC_PORT"
      route_ports_ref["ss_port"]="$CROSS_SS_PORT"
      route_ports_ref["anytls_port"]="$CROSS_ANYTLS_PORT"
      route_ports_ref["trojan_port"]="$CROSS_TROJAN_PORT"
      route_ports_ref["vision_port"]="$CROSS_VISION_PORT"
      route_ports_ref["xhttp_port"]="$CROSS_XHTTP_PORT"
      route_ports_ref["anyreality_port"]="${CROSS_ANYREALITY_PORT:-}"
      ;;
    *) route_context_fail "端口集必须是 normal 或 cross。" || return ;;
  esac
  route_ports_ref["port_set"]="$port_set"
  route_ports_ref["anyreality_enabled"]="$ANYREALITY_ENABLED"
}

route_context_validate() {
  local context_name="${1:-}" field key expected_ingress expected_egress
  local expected_rejected expected_port_set expected_dns_strategy
  local -a required_fields=(
    profile server ingress_family egress_family
    dns_mode dns_server dns_strategy rejected_ip_family port_set
    hy2_start hy2_end tuic_port ss_port anytls_port trojan_port
    vision_port xhttp_port anyreality_enabled anyreality_port
  )
  local -A allowed_fields=()

  route_context_is_associative "$context_name" \
    || route_context_fail "必须传入关联数组。" || return
  local -n route_validate_ref="$context_name"

  for field in "${required_fields[@]}"; do
    allowed_fields[$field]=1
    [[ -n "${route_validate_ref[$field]+present}" ]] \
      || route_context_fail "缺少字段 ${field}。" || return
  done
  for key in "${!route_validate_ref[@]}"; do
    [[ -n "${allowed_fields[$key]+allowed}" ]] \
      || route_context_fail "未知字段 ${key}。" || return
  done

  case "${route_validate_ref[profile]}" in
    v4)
      expected_ingress=ipv4
      expected_egress=ipv4
      expected_port_set=normal
      ;;
    v6)
      expected_ingress=ipv6
      expected_egress=ipv6
      expected_port_set=normal
      ;;
    v4-to-v6)
      expected_ingress=ipv4
      expected_egress=ipv6
      expected_port_set=cross
      ;;
    v6-to-v4)
      expected_ingress=ipv6
      expected_egress=ipv4
      expected_port_set=cross
      ;;
    *) route_context_fail "未知线路 ${route_validate_ref[profile]}。" || return ;;
  esac
  [[ "${route_validate_ref[ingress_family]}" == "$expected_ingress" ]] \
    || route_context_fail "${route_validate_ref[profile]} 的入站地址族不一致。" || return
  [[ "${route_validate_ref[egress_family]}" == "$expected_egress" ]] \
    || route_context_fail "${route_validate_ref[profile]} 的出站地址族不一致。" || return
  [[ "${route_validate_ref[port_set]}" == "$expected_port_set" ]] \
    || route_context_fail "${route_validate_ref[profile]} 的端口集不一致。" || return

  case "$expected_ingress" in
    ipv4) is_ipv4_literal "${route_validate_ref[server]}" ;;
    ipv6) is_ipv6_literal "${route_validate_ref[server]}" ;;
  esac || route_context_fail "server 与入站地址族不一致。" || return

  case "$expected_egress" in
    ipv4)
      expected_rejected=ipv6
      expected_dns_strategy=ipv4_only
      ;;
    ipv6)
      expected_rejected=ipv4
      expected_dns_strategy=ipv6_only
      ;;
  esac
  [[ "${route_validate_ref[rejected_ip_family]}" == "$expected_rejected" ]] \
    || route_context_fail "拒绝地址族与出站方向不一致。" || return
  [[ "${route_validate_ref[dns_strategy]}" == "$expected_dns_strategy" ]] \
    || route_context_fail "DNS 策略与出站方向不一致。" || return
  case "${route_validate_ref[dns_mode]}" in
    public)
      case "$expected_egress" in
        ipv4) is_ipv4_literal "${route_validate_ref[dns_server]}" ;;
        ipv6) is_ipv6_literal "${route_validate_ref[dns_server]}" ;;
      esac || route_context_fail "公共 DNS 与出站地址族不一致。" || return
      ;;
    akdns)
      [[ "$expected_egress" == ipv4 ]] \
        && is_ipv4_literal "${route_validate_ref[dns_server]}" \
        || route_context_fail "AKDNS 只接受 IPv4 出站解析地址。" || return
      ;;
    *) route_context_fail "DNS 模式必须是 public 或 akdns。" || return ;;
  esac

  for field in \
    hy2_start hy2_end tuic_port ss_port anytls_port trojan_port \
    vision_port xhttp_port; do
    route_context_port_is_valid "${route_validate_ref[$field]}" \
      || route_context_fail "${field} 不是有效端口。" || return
  done
  (( 10#${route_validate_ref[hy2_start]} <= 10#${route_validate_ref[hy2_end]} )) \
    || route_context_fail "Hysteria2 端口范围倒置。" || return
  case "${route_validate_ref[anyreality_enabled]}" in
    true)
      route_context_port_is_valid "${route_validate_ref[anyreality_port]}" \
        || route_context_fail "AnyReality 已启用但端口无效。" || return
      ;;
    false)
      [[ -z "${route_validate_ref[anyreality_port]}" ]] \
        || route_context_fail "AnyReality 已禁用但仍提供端口。" || return
      ;;
    *) route_context_fail "AnyReality 能力必须是 true 或 false。" || return ;;
  esac
}

render_subscription_route() {
  local context_name="${1:-}"
  (( $# == 1 )) || route_context_fail "渲染入口只接受一个具名上下文。" || return
  route_context_validate "$context_name" || return
  local -n route_render_ref="$context_name"
  local profile="${route_render_ref[profile]}"
  local server="${route_render_ref[server]}"
  local ingress_ip_version="${route_render_ref[ingress_family]}"
  local dns_server="${route_render_ref[dns_server]}"
  local dns_mode="${route_render_ref[dns_mode]}"
  local dns_strategy="${route_render_ref[dns_strategy]}"
  local rejected_ip_version
  local route_hy2_start="${route_render_ref[hy2_start]}"
  local route_hy2_end="${route_render_ref[hy2_end]}"
  local route_tuic_port="${route_render_ref[tuic_port]}"
  local route_ss_port="${route_render_ref[ss_port]}"
  local route_anytls_port="${route_render_ref[anytls_port]}"
  local route_trojan_port="${route_render_ref[trojan_port]}"
  local route_vision_port="${route_render_ref[vision_port]}"
  local route_xhttp_port="${route_render_ref[xhttp_port]}"
  local route_anyreality_port="${route_render_ref[anyreality_port]}"
  local route_anyreality_enabled="${route_render_ref[anyreality_enabled]}"

  case "${route_render_ref[rejected_ip_family]}" in
    ipv4) rejected_ip_version=4 ;;
    ipv6) rejected_ip_version=6 ;;
  esac

  render_client_yaml "${NEKO_SUB_DIR}/mihomo-${profile}.yaml" yes \
    "$server" "$ingress_ip_version" \
    "$route_hy2_start" "$route_hy2_end" "$route_tuic_port" "$route_ss_port" \
    "$route_anytls_port" "$route_trojan_port" "$route_vision_port" "$route_xhttp_port" \
    "$dns_mode" "$dns_server"
  # Stash does not implement XHTTP; each strict route has six nodes.
  render_stash_yaml "${NEKO_SUB_DIR}/stash-${profile}.yaml" "$server" \
    "$route_hy2_start" "$route_hy2_end" "$route_tuic_port" "$route_ss_port" \
    "$route_anytls_port" "$route_trojan_port" "$route_vision_port" \
    "$dns_mode" "$dns_server"
  render_shadowrocket "${NEKO_SUB_DIR}/shadowrocket-${profile}.txt" "$server" \
    "$route_hy2_start" "$route_hy2_end" "$route_tuic_port" "$route_ss_port" \
    "$route_anytls_port" "$route_trojan_port" "$route_vision_port" "$route_xhttp_port" \
    "$route_anyreality_port" "$route_anyreality_enabled"
  # Official sing-box Remote Profiles are complete JSON configurations.
  render_sing_box_client "${NEKO_SUB_DIR}/sing-box-${profile}.json" \
    "$server" "$dns_server" "$dns_mode" "$dns_strategy" "$rejected_ip_version" \
    "$route_hy2_start" "$route_hy2_end" "$route_tuic_port" "$route_ss_port" \
    "$route_anytls_port" "$route_trojan_port" "$route_vision_port" \
    "$route_anyreality_port" "$route_anyreality_enabled"
}

render_subscriptions() {
  local akdns_resolver="" v4_dns_mode=public v4_dns_server=1.1.1.1
  local -A route_context=()
  case "${NEKO_AKDNS_CLIENT_MODE:-auto}" in
    on)
      akdns_resolver="${NEKO_AKDNS_CLIENT_RESOLVER:-}"
      is_ipv4_literal "$akdns_resolver" \
        || die "AKDNS 客户端解析地址无效：${akdns_resolver:-empty}"
      ;;
    off) ;;
    auto)
      akdns_resolver="$(managed_akdns_resolver 2>/dev/null || true)"
      ;;
    *) die "不支持的 AKDNS 客户端渲染模式：${NEKO_AKDNS_CLIENT_MODE}" ;;
  esac
  if [[ -n "$akdns_resolver" ]]; then
    v4_dns_mode=akdns
    v4_dns_server="$akdns_resolver"
  fi
  mkdir -p "$NEKO_SUB_DIR"
  rm -f -- \
    "${NEKO_SUB_DIR}/mihomo-v4.yaml" \
    "${NEKO_SUB_DIR}/mihomo-v6.yaml" \
    "${NEKO_SUB_DIR}/stash-v4.yaml" \
    "${NEKO_SUB_DIR}/stash-v6.yaml" \
    "${NEKO_SUB_DIR}/shadowrocket-v4.txt" \
    "${NEKO_SUB_DIR}/shadowrocket-v6.txt" \
    "${NEKO_SUB_DIR}/sing-box-v4.json" \
    "${NEKO_SUB_DIR}/sing-box-v6.json" \
    "${NEKO_SUB_DIR}/mihomo-v4-to-v6.yaml" \
    "${NEKO_SUB_DIR}/mihomo-v6-to-v4.yaml" \
    "${NEKO_SUB_DIR}/stash-v4-to-v6.yaml" \
    "${NEKO_SUB_DIR}/stash-v6-to-v4.yaml" \
    "${NEKO_SUB_DIR}/shadowrocket-v4-to-v6.txt" \
    "${NEKO_SUB_DIR}/shadowrocket-v6-to-v4.txt" \
    "${NEKO_SUB_DIR}/sing-box-v4-to-v6.json" \
    "${NEKO_SUB_DIR}/sing-box-v6-to-v4.json"
  if network_mode_has_ipv4; then
    route_context=(
      [profile]=v4
      [server]="$SUBSCRIPTION_IPV4_ADDRESS"
      [ingress_family]=ipv4
      [egress_family]=ipv4
      [dns_mode]="$v4_dns_mode"
      [dns_server]="$v4_dns_server"
      [dns_strategy]=ipv4_only
      [rejected_ip_family]=ipv6
    )
    route_context_set_ports route_context normal
    render_subscription_route route_context
  fi
  if network_mode_has_ipv6; then
    route_context=(
      [profile]=v6
      [server]="$SUBSCRIPTION_IPV6_ADDRESS"
      [ingress_family]=ipv6
      [egress_family]=ipv6
      [dns_mode]=public
      [dns_server]="2606:4700:4700::1111"
      [dns_strategy]=ipv6_only
      [rejected_ip_family]=ipv4
    )
    route_context_set_ports route_context normal
    render_subscription_route route_context
  fi
  if network_mode_has_cross_routes; then
    route_context=(
      [profile]=v4-to-v6
      [server]="$SUBSCRIPTION_IPV4_ADDRESS"
      [ingress_family]=ipv4
      [egress_family]=ipv6
      [dns_mode]=public
      [dns_server]="2606:4700:4700::1111"
      [dns_strategy]=ipv6_only
      [rejected_ip_family]=ipv4
    )
    route_context_set_ports route_context cross
    render_subscription_route route_context
    route_context=(
      [profile]=v6-to-v4
      [server]="$SUBSCRIPTION_IPV6_ADDRESS"
      [ingress_family]=ipv6
      [egress_family]=ipv4
      [dns_mode]="$v4_dns_mode"
      [dns_server]="$v4_dns_server"
      [dns_strategy]=ipv4_only
      [rejected_ip_family]=ipv6
    )
    route_context_set_ports route_context cross
    render_subscription_route route_context
  fi
}

render_all() {
  load_state
  mkdir -p "$NEKO_CONFIG_DIR" "$NEKO_SUB_DIR"
  render_sing_box
  render_xray
  render_hysteria
  render_subscriptions
  render_caddy
}
